mapper.select:
SELECT FROM sys_menu WHERE del_flag = '0'
AND menu_name ILIKE CONCAT('%', #{query.menuName}, '%')
AND menu_type = #{query.menuType}
AND permission_code ILIKE CONCAT('%', #{query.permissionCode}, '%')
AND status = #{query.status}
ORDER BY parent_id ASC, order_num ASC, id ASC

SELECT COUNT(1)
FROM sys_menu
WHERE permission_code = #{permissionCode}
  AND del_flag = '0'

    AND id != #{excludeId}

SELECT DISTINCT FROM sys_menu m JOIN sys_role_menu rm ON rm.menu_id = m.id JOIN sys_role r ON r.id = rm.role_id AND r.del_flag = '0' AND r.status = '0' WHERE m.del_flag = '0' AND m.status = '0' AND m.menu_type IN ('M', 'C') AND r.id IN
#{roleId}
ORDER BY m.parent_id ASC, m.order_num ASC, m.id ASC

SELECT DISTINCT m.permission_code FROM sys_menu m JOIN sys_role_menu rm ON rm.menu_id = m.id JOIN sys_role r ON r.id = rm.role_id AND r.del_flag = '0' AND r.status = '0' WHERE m.del_flag = '0' AND m.status = '0' AND m.permission_code IS NOT NULL AND m.permission_code != '' AND r.id IN
#{roleId}
ORDER BY m.permission_code ASC
